define([
    'external/genetic/genetic',
    'gram/base/Base',
    'gram/base/Color',
    'gram/editor/ability/Ability',
    'gram/editor/ability/ConstrainedLayoutable',
    'gram/editor/ability/Containable',
    'gram/editor/ability/HandleSelectable',
    'gram/editor/ability/Layoutable',
    'gram/editor/ability/Nestable',
    'gram/editor/ability/Movable',
    'gram/editor/ability/Resizable',
    'gram/editor/ability/Selectable',
    'gram/editor/ability/Undetachable',
    'gram/editor/ability/XYLayoutable',
    'gram/editor/command/Command',
    'gram/editor/controller/Controller',
    'gram/editor/controller/ControllerFactory',
    'gram/editor/controller/ControllerRuleFactory',
    'gram/editor/handle/Handle',
    'gram/editor/handle/MoveHandle',
    'gram/editor/model/BaseModel',
    'gram/editor/model/ModelFactory',
    'gram/editor/system/Domain',
    'gram/editor/system/GraphicEditor',
    'gram/editor/system/GraphicViewer',
    'gram/editor/system/event/GraphicKeyHandler',
    'gram/editor/system/event/KeyHandler',
    'gram/editor/tool/ResizeTracker',
    'gram/editor/tool/Tool',
    'gram/env/Debugger',
    'gram/view/geometry/Geometry',
    'gram/view/geometry/Point',
    'gram/view/geometry/PointList',
    'gram/view/geometry/Rectangle',
    'gram/view/layout/StackLayout',
    'gram/view/layout/XYLayout',
    'gram/view/system/context/DefaultGraphicContextFactory',
    'gram/view/system/context/GraphicContext',
    'gram/view/system/event/EventTransmitter',
    'gram/view/system/GramShell',
    'gram/view/update-manager/AsyncUpdateManager',
    'gram/view/update-manager/UpdateManager',
    'gram/view/widget/connection/anchor/CardinalAnchor',
    'gram/view/widget/connection/anchor/EdgeAnchor',
    'gram/view/widget/connection/Connection',
    'gram/view/widget/connection/decoration/PolygonDecoration',
    'gram/view/widget/connection/decoration/PolylineDecoration',
    'gram/view/widget/html/Div',
    'gram/view/widget/svg/Circle',
    'gram/view/widget/svg/Ellipse',
    'gram/view/widget/svg/G',
    'gram/view/widget/svg/Polygon',
    'gram/view/widget/svg/PolygonShape',
    'gram/view/widget/svg/Polyline',
    'gram/view/widget/svg/Rect',
    'gram/view/widget/svg/Svg',
    'gram/view/widget/Widget'
], function (
    genetic,
    Base,
    Color,
    Ability,
    ConstrainedLayoutable,
    Containable,
    HandleSelectable,
    Layoutable,
    Nestable,
    Movable,
    Resizable,
    Selectable,
    Undetachable,
    XYLayoutable,
    Command,
    Controller,
    ControllerFactory,
    ControllerRuleFactory,
    Handle,
    MoveHandle,
    BaseModel,
    ModelFactory,
    Domain,
    GraphicEditor,
    GraphicViewer,
    GraphicKeyHandler,
    KeyHandler,
    ResizeTracker,
    Tool,
    Debugger,
    Geometry,
    Point,
    PointList,
    Rectangle,
    StackLayout,
    XYLayout,
    DefaultGraphicContextFactory,
    GraphicContext,
    EventTransmitter,
    GramShell,
    AsyncUpdateManager,
    UpdateManager,
    CardinalAnchor,
    EdgeAnchor,
    Connection,
    PolygonDecoration,
    PolylineDecoration,
    Div,
    Circle,
    Ellipse,
    G,
    Polygon,
    PolygonShape,
    Polyline,
    Rect,
    Svg,
    Widget
) {
    'use strict';

    var gram = {
        base: {
            Base: Base,
            Color: Color
        },
        editor: {
            ability: {
                Ability: Ability,
                ConstrainedLayoutable: ConstrainedLayoutable,
                Containable: Containable,
                HandleSelectable: HandleSelectable,
                Layoutable: Layoutable,
                Nestable: Nestable,
                Movable: Movable,
                Resizable: Resizable,
                Selectable: Selectable,
                Undetachable: Undetachable,
                XYLayoutable: XYLayoutable
            },
            command: {
                Command: Command
            },
            controller: {
                Controller: Controller,
                ControllerFactory: ControllerFactory
            },
            handle: {
                Handle: Handle,
                MoveHandle: MoveHandle
            },
            model: {
                BaseModel: BaseModel,
                ModelFactory: ModelFactory
            },
            system: {
                Domain: Domain,
                GraphicEditor: GraphicEditor,
                GraphicViewer: GraphicViewer,
                event: {
                    GraphicKeyHandler: GraphicKeyHandler,
                    KeyHandler: KeyHandler
                }
            },
            tool: {
                ResizeTracker: ResizeTracker,
                Tool: Tool
            }
        },
        env: {
            Debugger: Debugger
        },
        util: {
            genetic: genetic
        },
        view: {
            geometry: {
                Geometry: Geometry,
                Point: Point,
                PointList: PointList,
                Rectangle: Rectangle
            },
            layout: {
                StackLayout: StackLayout,
                XYLayout: XYLayout
            },
            system: {
                context : {
                    DefaultGraphicContextFactory: DefaultGraphicContextFactory,
                    GraphicContext: GraphicContext
                },
                event: {
                    EventTransmitter: EventTransmitter
                },
                GramShell: GramShell
            },
            updateManager: {
                AsyncUpdateManager: AsyncUpdateManager,
                UpdateManager: UpdateManager
            },
            widget: {
                connection: {
                    anchor: {
                        CardinalAnchor: CardinalAnchor,
                        EdgeAnchor: EdgeAnchor
                    },
                    decoration : {
                        PolygonDecoration: PolygonDecoration,
                        PolylineDecoration: PolylineDecoration
                    },
                    Connection: Connection
                },
                html: {
                    Div: Div
                },
                svg: {
                    Circle: Circle,
                    Ellipse: Ellipse,
                    G: G,
                    Polygon: Polygon,
                    PolygonShape: PolygonShape,
                    Polyline: Polyline,
                    Rect: Rect,
                    Svg: Svg
                },
                Widget: Widget
            }
        }
    };

    return gram;
});
